package ge.opensoft.openservice;
import static ge.opensoft.openservice.Values.*;
import static ge.opensoft.openservice.TypedFields.require;
import java.sql.SQLException;
import java.util.*;
import org.apache.commons.codec.digest.DigestUtils;
/** Checked customer intake with live account/contact and support-team record restrictions. */
final class CustomerCases {
 private CustomerCases() {}
 static void insertion(Store.Db db,Map<String,Object> item){if("customer_case".equals(item.get("table")) && !db.customerIntake)throw new Failure(409,"Create customer cases through entitled customer intake");}
 static String filter(Store.Db db,String record,List<Object> parameters){
  String scope;if("requester".equals(db.viewerRole)){parameters.add(db.viewerId);scope="c.user_id=? AND a.active=1 AND EXISTS(SELECT 1 FROM os_customer_contact t WHERE t.user_id=c.user_id AND t.account_id=c.account_id AND t.active=1)";}else if("agent".equals(db.viewerRole)){parameters.add(db.viewerId);scope="EXISTS(SELECT 1 FROM os_group_member m JOIN os_record g ON g.sys_id=m.group_id AND g.\"table\"='sys_user_group' WHERE m.user_id=? AND m.group_id=a.group_id)";}else scope="1=0";
  return "NOT EXISTS(SELECT 1 FROM os_record cr WHERE cr.sys_id="+record+" AND cr.\"table\"='customer_case' AND NOT EXISTS(SELECT 1 FROM os_customer_case c JOIN os_customer_account a ON a.account_id=c.account_id WHERE c.record_id=cr.sys_id AND "+scope+"))";
 }
 static Map<String,Object> offering(Store.Db db,String id)throws SQLException{var entitlement=CustomerEntitlements.eligible(db,id,System.currentTimeMillis());String account=entitlement.get("account_id").toString();return map("entitlement",entitlement,"account",map("name",CustomerAccounts.account(db,account).get("name"),"revision",CustomerAccounts.account(db,account).get("revision")),"contact_revision",CustomerAccounts.contact(db,db.viewerId).get("revision"));}
 static Map<String,Object> create(Store.Db db,String id,Object input)throws SQLException{
  return create(db,id,input,Service.account(db,db.viewerId).get("name").toString());
 }
 static Map<String,Object> create(Store.Db db,String id,Object input,String actor)throws SQLException{
  if(!"requester".equals(db.viewerRole))throw new Failure(403,"Customer requester access required");if(db.postgres)db.all("SELECT pg_advisory_xact_lock(18439,4)");var body=object(input);require(body.keySet().equals(Set.of("account_revision","contact_revision","entitlement_revision","summary","description","key")),"Provide reviewed support revisions, summary, description and key");String summary=WorkJobs.text(body.get("summary"),160),description=WorkJobs.text(body.get("description"),4000),key=WorkJobs.text(body.get("key"),32);require(key.matches("[0-9a-f]{32}"),"Use a 32-character intake key");var normalized=new TreeMap<>(body);normalized.put("entitlement_id",id);String fingerprint=DigestUtils.sha256Hex(JSON.writeValueAsString(normalized));var previous=db.one("SELECT record_id,fingerprint FROM os_customer_case WHERE user_id=? AND intake_key=?",db.viewerId,key);if(previous!=null){if(!fingerprint.equals(previous.get("fingerprint")))throw new Failure(409,"Intake key already identifies different work");return Service.readRecord(db,"customer_case",previous.get("record_id").toString());}
  var entitlement=CustomerEntitlements.eligible(db,id,System.currentTimeMillis());var contact=CustomerAccounts.contact(db,db.viewerId);var account=CustomerAccounts.account(db,entitlement.get("account_id").toString());ProblemInvestigations.revision(body.get("account_revision"),account.get("revision"));ProblemInvestigations.revision(body.get("contact_revision"),contact.get("revision"));ProblemInvestigations.revision(body.get("entitlement_revision"),entitlement.get("revision"));Map<String,Object> item;try{db.customerIntake=true;item=Service.create(db,"customer_case",map("short_description",summary,"description",description),actor);}finally{db.customerIntake=false;}
  db.update("INSERT INTO os_customer_case(record_id,account_id,user_id,entitlement_id,account_revision,contact_revision,entitlement_revision,account_name,entitlement_name,intake_key,fingerprint,created) VALUES(?,?,?,?,?,?,?,?,?,?,?,?)",item.get("sys_id"),account.get("account_id"),db.viewerId,id,account.get("revision"),contact.get("revision"),entitlement.get("revision"),account.get("name"),entitlement.get("name"),key,fingerprint,now());db.update("INSERT INTO os_requester_record(record_id,user_id) VALUES(?,?)",item.get("sys_id"),db.viewerId);Service.audit(db,item,actor,"customer.intake",map("entitlement_revision",entitlement.get("revision")));return item;
 }
 static Map<String,Object> snapshot(Store.Db db,String id)throws SQLException{Service.readRecord(db,"customer_case",id);if(!FieldAccess.allowed(db,Service.schema(db,"customer_case"),"description"))throw new Failure(403,"Case description access required");return db.one("SELECT account_name,entitlement_name,account_revision,contact_revision,entitlement_revision,created FROM os_customer_case WHERE record_id=?",id);}
 static Map<String,Object> portal(Store.Db db,Map<String,String> args)throws SQLException{
  if(!Set.of("admin","agent","requester").contains(db.viewerRole))throw new Failure(403,"Customer requester or support staff access required");require(Set.of("limit","offset").containsAll(args.keySet()),"Use limit and offset only");int limit=Service.number(args.getOrDefault("limit","20"),1,100),offset=Service.number(args.getOrDefault("offset","0"),0,Integer.MAX_VALUE);var offers=new ArrayList<Map<String,Object>>();Map<String,Object> account=null;
  if("requester".equals(db.viewerRole)){var contact=CustomerAccounts.contact(db,db.viewerId);if(((Number)contact.get("active")).intValue()==1){var candidate=CustomerAccounts.account(db,contact.get("account_id").toString());if(((Number)candidate.get("active")).intValue()==1){account=map("name",candidate.get("name"));for(var row:CustomerEntitlements.list(db,candidate.get("account_id").toString()))try{offers.add(CustomerEntitlements.eligible(db,row.get("entitlement_id").toString(),System.currentTimeMillis()));}catch(Failure unavailable){ /* Current eligibility hides unavailable support. */ }}}}
  var page=Service.page(db,"customer_case",Map.of("sysparm_limit",Integer.toString(limit),"sysparm_offset",Integer.toString(offset)),"");return map("account",account,"entitlements",offers,"cases",page.rows(),"total",page.total(),"limit",limit,"offset",offset,"next_offset",page.hasNext()?(long)offset+limit:null);
 }
}
